  /** «Какая категория годности по статье …». */
  categories: string;
  /** «Какие документы нужны». */
  documents: string[];
  /** «Ошибки на медкомиссии». */
  mistakes: string[];
  /** «Что делать, если военкомат не принимает диагноз». */
  ifRejected: string;
  /** FAQ на 5–7 вопросов (раскрытый текст + FAQPage schema). */
